let counts = items.map(() => 0);
let spent = 0;
const $ = id => document.getElementById(id);

function fmt(n) { return "$" + Math.round(n).toLocaleString("es-AR"); }
function fmtC(n) {
  if (n >= 1e9) return "$" + (n/1e9).toFixed(2) + "B";
  if (n >= 1e6) return "$" + (n/1e6).toFixed(1) + "M";
  if (n >= 1e3) return "$" + Math.round(n/1e3) + "K";
  return fmt(n);
}

function updateTopbar() {
  const rem = TOTAL - spent;
  const pct = Math.min(100, spent/TOTAL*100);
  const b = $("balance");
  b.textContent = fmt(rem);
  b.classList.toggle("low", rem < TOTAL*0.15);
  const f = $("progress-fill");
  f.style.width = pct.toFixed(2) + "%";
  f.classList.toggle("done", pct >= 100);
  $("pct-label").textContent = pct.toFixed(1) + "% gastado  ·  USD " + Math.round(rem/USD_RATE).toLocaleString("es-AR") + " restantes";
  $("banner").style.display = pct >= 100 ? "block" : "none";
}

function updateReceipt() {
  const body = $("receipt-body");
  const lines = items.map((item,i) => ({item, count:counts[i], sub:counts[i]*item.price})).filter(l=>l.count>0);
  if (!lines.length) { body.innerHTML='<div id="receipt-empty">Todavía no gastaste nada 👀</div>'; return; }
  body.innerHTML = lines.map(l=>`
    <div class="r-line">
      <img class="r-thumb" src="${l.item.img}" alt="${l.item.name}" />
      <div class="r-name">${l.item.name}<span>× ${l.count}</span></div>
      <div class="r-amt">${fmtC(l.sub)}</div>
    </div>`).join("") +
    `<div id="receipt-total-row"><div id="receipt-total-label">Total gastado</div><div id="receipt-total-val">${fmt(spent)}</div></div>`;
}

function refreshCard(i) {
  const card = document.getElementById("c-"+i);
  const item = items[i];
  const qty = counts[i];
  const qEl = card.querySelector(".item-qty");
  qEl.textContent = qty;
  qEl.classList.remove("pop"); void qEl.offsetWidth; qEl.classList.add("pop");
  card.querySelector(".ctrl-btn.minus").disabled = qty===0;
  card.querySelector(".ctrl-btn.plus").disabled = item.price>0 && spent+item.price>TOTAL;
  card.querySelector(".item-subtotal").textContent = qty>0 ? fmt(qty*item.price) : "";
  card.classList.toggle("bought", qty>0);
}

function add(i) {
  if (items[i].price>0 && spent+items[i].price>TOTAL) return;
  counts[i]++; spent+=items[i].price;
  refreshCard(i); updateTopbar(); updateReceipt();
}
function sub(i) {
  if (counts[i]===0) return;
  counts[i]--; spent-=items[i].price;
  refreshCard(i); updateTopbar(); updateReceipt();
}
function resetAll() {
  counts.fill(0); spent=0;
  document.querySelectorAll(".item-card").forEach(c=>{
    c.querySelector(".item-qty").textContent="0";
    c.querySelector(".item-subtotal").textContent="";
    c.querySelector(".ctrl-btn.minus").disabled=true;
    c.querySelector(".ctrl-btn.plus").disabled=false;
    c.classList.remove("bought");
  });
  updateTopbar(); updateReceipt();
}

function render() {
  const wrap = $("items-wrap");
  const grid = document.createElement("div");
  grid.className = "items-grid";
  items.forEach((item,i) => {
    const card = document.createElement("div");
    card.className = "item-card"; card.id = "c-"+i;
    card.innerHTML = `
      <img class="item-img" src="${item.img}" alt="${item.name}" loading="lazy" />
      <div class="item-body">
        <div class="item-name">${item.name}</div>
        <div class="item-price">${item.price===0?"Gratis":fmt(item.price)}</div>
        <div class="item-hint">${item.hint}</div>
      </div>
      <div class="item-footer">
        <div>
          <div class="item-qty">0</div>
          <div class="item-subtotal"></div>
        </div>
        <div class="item-controls">
          <button class="ctrl-btn minus" onclick="sub(${i})" disabled>−</button>
          <button class="ctrl-btn plus" onclick="add(${i})">+</button>
        </div>
      </div>
    `;
    grid.appendChild(card);
  });
  wrap.appendChild(grid);
}

render(); updateTopbar();